var Layout_default = _sfc_main;

//#endregion
//#region src/theme/factory.ts
function withAgilebotTheme(config) {
	return {
		extends: DefaultTheme,
		Layout: Layout_default,
		enhanceApp: ({ app, router, siteData }) => {
			app.use(TwoslashFloatingVue);
			app.provide(InjectionKey, { layoutSwitch: {
				defaultMode: LayoutMode.FullWidth,
				disableAnimation: true
			} });
			if (config?.gaTrackingId) googleAnalytics({ id: config.gaTrackingId });
			router.onBeforePageLoad = (to) => {
				if (!inBrowser) return;
				const base = siteData.value.base;
				if (isSamePath(to, base) && Object.keys(siteData.value.locales).length > 0) {
					const cachedLang = localStorage.getItem("vp-lang");
					const langHref = cachedLang ? joinURL(base, cachedLang) : joinURL(base, siteData.value.lang);
					location.replace(withTrailingSlash(langHref));
				}
			};
			if (config?.enhanceApp) config.enhanceApp(app);
		}
	};
}

//#endregion
export { withAgilebotTheme };